dule-federation/nextjs-mf was designed to consume.\n\n- remote/vite.config.js: use @originjs/vite-plugin-federation, add shared\n- remote/package.json: swap @module-federation/vite for @originjs/vite-plugin-federation\n- shell/next.config.js: update remote URL and watch path to /assets/remoteEntry.js\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>","tree":{"sha":"3ee4e8491119da349df87677846515619bee6f72","url":"https://api.github.com/repos/abdulhanna/micro-frontend/git/trees/3ee4e8491119da349df87677846515619bee6f72"},"url":"https://api.github.com/repos/abdulhanna/micro-frontend/git/commits/6d37de0b5d829d8aee5d600d87391b9777ca9701","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/178729901?v=4","events_url":"https://api.github.com/users/Aiwan01/events{/privacy}","followers_url":"https://api.github.com/users/Aiwan01/followers","following_url":"https://api.github.com/users/Aiwan01/following{/other_user}","gists_url":"https://api.github.com/users/Aiwan01/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Aiwan01","id":178729901,"login":"Aiwan01","node_id":"U_kgDOCqczrQ","organizations_url":"https://api.github.com/users/Aiwan01/orgs","received_events_url":"https://api.github.com/users/Aiwan01/received_events","repos_url":"https://api.github.com/users/Aiwan01/repos","site_admin":false,"starred_url":"https://api.github.com/users/Aiwan01/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Aiwan01/subscriptions","type":"User","url":"https://api.github.com/users/Aiwan01","user_view_type":"public"},"html_url":"https://github.com/abdulhanna/micro-frontend/commit/6d37de0b5d829d8aee5d600d87391b9777ca9701","node_id":"C_kwDOSPtlh9oAKDZkMzdkZTBiNWQ4MjlkOGFlZTVkNjAwZDg3MzkxYjk3NzdjYTk3MDE","parents":[{"html_url":"https://github.com/abdulhanna/micro-frontend/commit/15e4333e081d8a0b1e1b855dcb4a6e2b53007897","sha":"1